22	\begin{table}[H]
23	\centering
24	\begin{tabular}{p{0.22\textwidth} p{0.34\textwidth} p{0.34\textwidth}}
25	\toprule
26	方法 & 优势 & 典型场景 \\
27	\midrule
28	MoG & 提供有限且 interpretable 的混合模式 & 低维连续控制 \\
29	Autoregressive & 维度分解，捕捉细粒度 correlation & 自动驾驶行为序列 \\
30	Diffusion & 可做 implicit sampling & 高维机器人操作 \\
31	\bottomrule
32	\end{tabular}
33	\caption{表达性策略的典型架构}
34	\end{table}
